import java.util.Scanner;
public class SelfDrivingCarBenefits {
 public static void main(String[] args) {
 Scanner sc = new Scanner(System.in);
 System.out.println("Enter a phrase to explain the benefits of self-driving cars: ");
 String phrase = sc.nextLine();

 if (phrase.contains("safe") && phrase.contains("efficient")) {
 System.out.println("Self-driving cars: safe and efficient travel.");
 } else if (phrase.contains("time") && phrase.contains("optimize")) {
 System.out.println("Self-driving cars: optimized travel time with communication.");
 } else {
 System.out.println("Sorry, please enter a phrase that includes the benefits of self-driving cars.");
 }

 sc.close();
 }

