// Check connection
if ($conn-connect_error) {
 die("Connection failed: " . $conn->connect_error);
}
// SQL query to get drinking age for each state
$sql = "SELECT state_name, drinking_age FROM state_info";
$result = $conn->query($sql);
// Output results in a table
echo "

| State | Drinking Age |
| --- | --- |
";
if ($result->num_rows > 0) {
 while($row = $result->fetch_assoc()) {
 echo "| " . $row["state_name"]. " | " . $row["drinking_age"]. " |
";
 }
} else {
 echo "0 results";
}
echo "
";
$conn->close();
?>
