How can I create a program in [JavaScript] that generates a random Rubik's cube scramble and then provides me with the optimal solution to solve it? 
Here is a sample code to generate a random Rubik's cube scramble:
var moves = ["U", "D", "R", "L", "F", "B"];
var scramble = "";
for (var i = 0; i < 20; i++) {
 var moveIndex = Math.floor(Math.random() * moves.length);
 var move = moves[moveIndex];
 var suffix = "";
 if (Math.random() < 0.5) {
 suffix = "'";
 } else if (Math.random() < 0.3) {
 suffix = "2";
 }
 scramble += move + suffix + " ";
}
console.log("Scramble: " + scramble);
To get the optimal solution, you can use a Rubik's cube solver library like Cube Explorer or Kociemba algorithm. Here's an example of how to use Kociemba algorithm in JavaScript:
var solver = require('rubiks-cube-solver');
var scramble = "R U R' U' R' F R2 U' R' U' R U R' F'";
var solution = solver.solve(scramble);
console.log("Scramble: " + scramble);
console.log("Solution: " + solution);

