What are some examples of queries that involve at least one JOIN operation and one GROUP BY operation for the Items database table? Here are five unique combinations of conditions:
1. Return the average price of items for each category.
SELECT categories.category_name, AVG(items.price) AS average_price
FROM categories
INNER JOIN items ON categories.category_id = items.category_id
GROUP BY categories.category_name;
2. Return the total revenue for each month, along with the top-selling item for that month.
SELECT DATE_TRUNC('month', items.date_sold) AS month, items.item_name, SUM(items.price) AS total_revenue
FROM items
INNER JOIN sales ON items.item_id = sales.item_id
GROUP BY month, items.item_name
ORDER BY month, total_revenue DESC
LIMIT 1;
3. Return the number of items sold for each category, as well as the category with the highest number of sales.
SELECT categories.category_name, COUNT(items.item_id) AS num_sold
FROM categories
INNER JOIN items ON categories.category_id = items.category_id
INNER JOIN sales ON items.item_id = sales.item_id
GROUP BY categories.category_name
ORDER BY num_sold DESC
LIMIT 1;
4. Return the total revenue for each category, as well as the category with the highest revenue.
SELECT categories.category_name, SUM(items.price) AS total_revenue
FROM categories
INNER JOIN items ON categories.category_id = items.category_id
INNER JOIN sales ON items.item_id = sales.item_id
GROUP BY categories.category_name
ORDER BY total_revenue DESC
LIMIT 1;
5. Return the number of items sold by each employee, as well as the employee with the highest number of sales.
SELECT employees.employee_name, COUNT(items.item_id) AS num_sold
FROM employees
INNER JOIN sales ON employees.employee_id = sales.employee_id
INNER JOIN items ON sales.item_id = items.item_id
GROUP BY employees.employee_name
ORDER BY num_sold DESC
LIMIT 1;
